package ma.maarifculture.analytics.controller;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import ma.maarifculture.analytics.dto.ForecastDtos.*;import ma.maarifculture.analytics.dto.PageResponse;import ma.maarifculture.analytics.model.RecommendationStatus;import ma.maarifculture.analytics.service.ForecastService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/forecasting") @PreAuthorize("hasAnyRole('ADMINISTRATOR','MANAGER')") public class ForecastController {private final ForecastService service;public ForecastController(ForecastService s){service=s;}@PostMapping("/products/{productId}/generate")public ForecastResponse generate(@PathVariable Long productId){return service.generate(productId);}@PostMapping("/products/{productId}/recommend")public RecommendationResponse recommend(@PathVariable Long productId){return service.recommend(productId);}@GetMapping("/recommendations")public PageResponse<RecommendationResponse> list(@RequestParam(required=false) RecommendationStatus status,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return service.recommendations(status,page,size);}@PatchMapping("/recommendations/{id}/status")public RecommendationResponse status(@PathVariable Long id,@Valid @RequestBody StatusRequest request){return service.status(id,request.status());}}
